package com.codearchive.api.automation;
import com.codearchive.api.auth.AppUser; import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="github_commit_jobs", uniqueConstraints=@UniqueConstraint(columnNames={"user_id","capture_id"})) public class GithubCommitJob {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private AppUser user; @Column(name="capture_id",nullable=false) private String captureId; @Column(name="settings_generation",nullable=false) private long settingsGeneration; @Enumerated(EnumType.STRING) @Column(nullable=false) private CommitJobState state; private int attempts; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected GithubCommitJob(){} public GithubCommitJob(AppUser user,String captureId,long settingsGeneration){this.user=user;this.captureId=captureId;this.settingsGeneration=settingsGeneration;state=CommitJobState.PENDING;createdAt=updatedAt=Instant.now();} public Long getId(){return id;} public AppUser getUser(){return user;} public String getCaptureId(){return captureId;} public long getSettingsGeneration(){return settingsGeneration;} public CommitJobState getState(){return state;} public int getAttempts(){return attempts;} public Instant getUpdatedAt(){return updatedAt;} public void start(){state=CommitJobState.RUNNING;attempts++;updatedAt=Instant.now();} public void terminal(CommitJobState value){state=value;updatedAt=Instant.now();} public void retry(){state=CommitJobState.PENDING;updatedAt=Instant.now();}
}
